"use client";

import { useState } from "react";
import { cn } from "@/lib/utils";

export function CodeBlock({
  code,
  language = "bash",
  className,
}: {
  code: string;
  language?: string;
  className?: string;
}) {
  const [copied, setCopied] = useState(false);

  const handleCopy = async () => {
    await navigator.clipboard.writeText(code);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className={cn("relative group rounded-xl bg-codeblock border border-edge overflow-hidden", className)}>
      <div className="flex items-center justify-between px-4 py-2 border-b border-edge">
        <span className="text-xs text-muted font-mono">{language}</span>
        <button
          onClick={handleCopy}
          className="text-xs text-muted hover:text-heading transition-colors"
        >
          {copied ? "\u2713" : "Copy"}
        </button>
      </div>
      <pre className="p-4 overflow-x-auto">
        <code className="text-sm font-mono text-accent-cyan">{code}</code>
      </pre>
    </div>
  );
}

