        locale: lang,
        locales: i18n.languages?.map((l) => ({
          name: l === "en" ? "English" : "中文",
          locale: l,
        })),
        translations:
          lang === "zh"
            ? {
                search: "搜索文档",
                toc: "目录",
                lastUpdate: "最后更新",
                searchNoResult: "没有找到结果",
                previousPage: "上一页",
                nextPage: "下一页",
              }
            : undefined,
      }}
    >
